#include "rinkfit/joint_effective_input_v1.hpp"
#include <iostream>
using namespace rinkfit;using J=eventio::Json;
int main(int argc,char**argv){try{const auto request=JointEffectiveInputV1::strict_json(argv[1]);const auto began=std::chrono::steady_clock::now();JointEffectiveInputV1::install_prepared(request.at("effective_input_v1"),request.at("prepared_effective_input_v1"));const auto m=JointEffectiveInputV1::manifest();const auto p=JointEffectiveInputV1::prepared_receipt();const auto receipt=JointEffectiveInputV1::receipt();if(!JointEffectiveInputV1::prepared()||receipt.at("binding")!=request.at("effective_input_v1")||receipt.at("compiled_source_validator_sha256")!=m.at("compiled_source_validator_sha256")||receipt.at("solver_compiled_source_validator_sha256")!=RINKFIT_SOURCE_VALIDATOR_SHA||receipt.at("current_solver_reexecuted_historical_qualification")!=false)throw std::runtime_error("prepared proof/solver identities were conflated");const auto resolved=JointEffectiveInputV1::strict_json(JointEffectiveInputV1::pin(p.at("resolved_payload")));if(JointEffectiveInputV1::digest(resolved)!=m.at("resolved_metadata_sha256")||resolved.at("arrays")!=m.at("arrays")||resolved.at("row_count")!=m.at("raw_rows"))throw std::runtime_error("prepared resolved payload differs from actual original proof");const auto stats=eventio::verification_statistics();JointEffectiveInputV1::clear();
 int rejected=0;const auto out=std::filesystem::u8path(argv[2]).parent_path();auto reject=[&](J bad,const std::string&name){const auto path=out/(name+".json");bad.erase("binding");eventio::atomic_json(path,bad);const J binding={{"file",path.u8string()},{"sha256",eventio::file_sha256(path)}};bool refused=false;try{JointEffectiveInputV1::install_prepared(request.at("effective_input_v1"),binding);}catch(const std::exception&){refused=true;}JointEffectiveInputV1::clear();if(!refused)throw std::runtime_error("prepared mutation accepted: "+name);++rejected;};auto bad=p;bad["raw_rows"]=m.at("raw_rows").get<std::size_t>()+1;reject(bad,"wrong_raw_domain");bad=p;bad["proof_validator"]["compiled_source_validator_sha256"]=std::string(64,'0');reject(bad,"forged_original_validator");
 J result={{"schema","rinkfit.actual_prepared_input_boundary_test.v1"},{"passed",true},{"prepared",request.at("prepared_effective_input_v1")},{"cold_native_proof",p.at("cold_native_proof")},{"raw_rows",m.at("raw_rows")},{"source_dependencies",p.at("source_dependency_count")},{"original_proof_validator",p.at("proof_validator")},{"current_solver_compiled_validator",RINKFIT_SOURCE_VALIDATOR_SHA},{"original_identity_preserved",true},{"historical_source_math_replayed",false},{"rejections",rejected},{"source_file_verification",stats},{"elapsed_seconds",std::chrono::duration<double>(std::chrono::steady_clock::now()-began).count()},{"solver_started",false}};eventio::atomic_json(argv[2],result);std::cout<<result.dump()<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
